  { id: 'rogue', name: 'Errante', icon: '🗡️', tagline: 'Sombra e precisão', desc: 'Ágil e letal. Torne-se intocável por um instante e recupere vida.', hp: 84, atk: 12, def: 2, skill: 'Véu', skillIcon: '◌' }
];
