  rat: { name: 'Rato de cripta', icon: '🐀', hp: 18, atk: 5, xp: 12, gold: 3 },
  wisp: { name: 'Fogo-fátuo', icon: '👻', hp: 24, atk: 7, xp: 17, gold: 5 },
