103:     for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) grid[yy][xx] = 1;
104:   }
105:   rooms.sort((a, b) => a.cx - b.cx);
106:   for (let i = 1; i < rooms.length; i++) {
107:     const a = rooms[i - 1], b = rooms[i];
108:     if (Math.random() < .5) { carveH(grid, a.cx, b.cx, a.cy); carveV(grid, a.cy, b.cy, b.cx); }
109:     else { carveV(grid, a.cy, b.cy, a.cx); carveH(grid, a.cx, b.cx, b.cy); }
110:   }
111:   const start = rooms[0] || { cx: 3, cy: 3, x: 2, y: 2, w: 4, h: 3 };
112:   if (!rooms.length) for (let y = 2; y < 5; y++) for (let x = 2; x < 6; x++) grid[y][x] = 1;
113:   const end = rooms[rooms.length - 1] || start;
114:   const floor = { W, H, grid, rooms, start: { x: start.cx, y: start.cy }, stairs: { x: end.cx, y: end.cy }, explored: new Set(), enemies: [], items: [], turn: 0 };
