126:     if (!grid[y][x] || (x === floor.start.x && y === floor.start.y) || (floor.stairs && x === floor.stairs.x && y === floor.stairs.y)) continue;
127:     if (distance({ x, y }, floor.start) < 5 || (floor.stairs && distance({ x, y }, floor.stairs) < 2)) continue;
128:     free.push({ x, y });
129:   }
