138:   for (let i = 0; i < 2 + rngInt(3) && free.length; i++) floor.items.push({ type: 'chest', ...free.pop(), opened: false });
139:   for (let i = 0; i < 4 + rngInt(4) && free.length; i++) floor.items.push({ type: 'gold', ...free.pop(), amount: 5 + rngInt(13) });
